        "JavaScript": "test('2 人目が不合格なら false', () => {\n  expect(allPassed([80, 40, 90], 60)).toBe(false);\n});\ntest('0 人なら true', () => {\n  expect(allPassed([], 60)).toBe(true);\n});",
