        "C#": "[Fact]\npublic void ReturnsOrderWithSharedDependency()\n{\n    var result = InstallOrder(new()\n    {\n        [\"app\"] = new() { \"ui\", \"api\" },\n        [\"ui\"] = new() { \"core\" },\n        [\"api\"] = new() { \"core\" },\n        [\"core\"] = new(),\n    });\n    Assert.True(result.Ok);\n    var order = result.Order;\n    Assert.Equal(4, order.Count);\n    Assert.True(order.IndexOf(\"core\") < order.IndexOf(\"ui\"));\n    Assert.True(order.IndexOf(\"core\") < order.IndexOf(\"api\"));\n    Assert.True(order.IndexOf(\"ui\") < order.IndexOf(\"app\"));\n    Assert.True(order.IndexOf(\"api\") < order.IndexOf(\"app\"));\n}\n\n[Fact]\npublic void RealCycleFails()\n{\n    var deps = new Dictionary<string, List<string>>\n    {\n        [\"a\"] = new() { \"b\" },\n        [\"b\"] = new() { \"c\" },\n        [\"c\"] = new() { \"a\" },\n    };\n    Assert.False(InstallOrder(deps).Ok);\n}",
        "Kotlin": "@Test\nfun `共通の依存があっても導入順を返す`() {\n    val result = installOrder(\n        mapOf(\n            \"app\" to listOf(\"ui\", \"api\"),\n            \"ui\" to listOf(\"core\"),\n            \"api\" to listOf(\"core\"),\n            \"core\" to listOf(),\n        )\n    )\n    val order = assertIs<InstallResult.Ok>(result).order\n    assertEquals(4, order.size)\n    assertTrue(order.indexOf(\"core\") < order.indexOf(\"ui\"))\n    assertTrue(order.indexOf(\"core\") < order.indexOf(\"api\"))\n    assertTrue(order.indexOf(\"ui\") < order.indexOf(\"app\"))\n    assertTrue(order.indexOf(\"api\") < order.indexOf(\"app\"))\n}\n\n@Test\nfun `本当の循環は失敗を返す`() {\n    val deps = mapOf(\"a\" to listOf(\"b\"), \"b\" to listOf(\"c\"), \"c\" to listOf(\"a\"))\n    assertIs<InstallResult.Cycle>(installOrder(deps))\n}",
